def close(self) -> None:
    """Terminate the shell and release the pty. Safe to call twice."""
    if self._closed:
        return
    self._closed = True
    pid = self._child.pid
    # Shut the session down like closing a real terminal: SIGHUP to the
    # shell's whole process group first (this also kills any foreground
    # job, e.g. `sleep 100`), then SIGKILL for whatever survives.
    # Doing this *before* closing the file object lets the reader thread's
    # blocked read() return, so close() cannot deadlock on it.
    try:
        os.killpg(os.getpgid(pid), signal.SIGHUP)
    except OSError:
        pass  # process group already gone
    deadline = time.monotonic() + 2.0
    while time.monotonic() < deadline and self._child.isalive():
        time.sleep(0.05)
    try:
        os.killpg(os.getpgid(pid), signal.SIGKILL)
    except OSError:
        pass
    self._reader.join(timeout=2.0)
    try:
        self._child.close(force=False)
    except Exception:
        pass

